const pages = [];
try { pages.push($('Fetch Bulle 1630').first().json.data || ''); } catch (e) { pages.push(''); }
try { pages.push($('Fetch La Tour 1635').first().json.data || ''); } catch (e) { pages.push(''); }

const out = [];
const seen = new Set();
let markerOk = false;
const decode = s => (s || '').replace(/&#(\d+);/g, (_, c) => String.fromCharCode(c)).replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#x27;|&apos;/g, "'").replace(/\s+/g, ' ').trim();
for (const html of pages) {
  if (typeof html !== 'string' || !html) continue;
  if (html.includes('bien_search_advanced')) markerOk = true;
  const blocks = html.split('<article class="bien-article').slice(1);
  for (const b of blocks) {
    const href = (b.match(/data-href="([^"]+)"/) || [])[1];
    if (!href) continue;
    const id = href.replace(/^\//, '').split('-').slice(0, 2).join('-');
    if (seen.has(id)) continue;
    seen.add(id);
    const title = decode((b.match(/article-title"><a[^>]*>([^<]+)</) || ['',''])[1]);
    const addr = decode((b.match(/article-address">\s*([^<]+?)\s*</) || ['',''])[1]);
    const rm = (b.match(/class="pieces">\s*([\d.,]+)\s*pi[eè]ce/i) || [])[1];
    const rooms = rm ? parseFloat(rm.replace(',', '.')) : null;
    if (rooms === null || rooms < 2.5 || rooms > 3.5) continue;
    const priceRaw = decode((b.match(/article-price">\s*([^<]+)/) || ['',''])[1]);
    const pm = priceRaw.match(/CHF\s*([\d']+)/);
    const rent = pm ? parseInt(pm[1].replace(/'/g, ''), 10) : null;
    const img = (b.match(/article-img"\s+src="([^"]+)"/) || [])[1];
    const m2m = title.match(/(\d+)\s*m2/i);
    out.push({ json: {
      source: 'gerofinance',
      source_id: id,
      url: 'https://www.gerofinance.ch' + href,
      title: title + (addr ? ' — ' + addr : ''),
      rent_net: rent, rent_gross: null, charges: null,
      rooms, m2: m2m ? parseInt(m2m[1], 10) : null,
      commune: addr || 'Bulle', address_raw: addr || null,
      description: title, cross_key: null, published_at: null,
      images: img ? ['https://www.gerofinance.ch' + img] : []
    }});
  }
}
if (!markerOk) {
  throw new Error('gerofinance: search-page marker missing on both NPA pages — page structure changed or request blocked');
}
return out;
